// FUNCTION: BFME2 0x0038470E size=754 name=?sumOnlineMiscPrefs@@YAHH@Z evidence=N:ledger tier=A
Int sumOnlineMiscPrefs(Int profileID)
{
	Int total = 0;
	if (profileID == 0)
		return 0;

	UserPreferences prefs;
	AsciiString path;
	path.format("%s\\MiscPref%d.ini", "Online Files", profileID);
	prefs.load(path);

	if (prefs.find("0") != prefs.end())
		total = Msvcr71::atoi(prefs.find("0")->second.str());
	if (prefs.find("1") != prefs.end())
		total += Msvcr71::atoi(prefs.find("1")->second.str());
	if (prefs.find("2") != prefs.end())
		total += Msvcr71::atoi(prefs.find("2")->second.str());
	if (prefs.find("3") != prefs.end())
		total += Msvcr71::atoi(prefs.find("3")->second.str());
	if (prefs.find("4") != prefs.end())
		total += Msvcr71::atoi(prefs.find("4")->second.str());
	if (prefs.find("5") != prefs.end())
		total += Msvcr71::atoi(prefs.find("5")->second.str());

	return total;
}


// FUNCTION: BFME2 0x00384A00 size=98 name=?GetAdditionalDisconnectsFromUserFile@@YAHH@Z evidence=N:ledger tier=A
Int GetAdditionalDisconnectsFromUserFile(Int profileID)
{
	Int retval = sumOnlineMiscPrefs(profileID);

	if (profileID == 0)
		return 0;

	if (TheGameSpyInfo->getAdditionalDisconnects() > 0 && !retval)
		TheGameSpyInfo->clearAdditionalDisconnects();

	if (TheGameSpyInfo->getAdditionalDisconnects() != -1)
		return TheGameSpyInfo->getAdditionalDisconnects();

	return retval;
}


